import requests

MODEL_URL = 'https://llm.example.com/v1/generate'

def summarize(text, token):
    response = requests.post(
        MODEL_URL,
        headers={'Authorization': f'Bearer {token}'},
        json={
            'model': 'summary-model',
            'input': text,
        },
    )
    response.raise_for_status()
    return response.json()['output']

